input.command:
$P='<PLUGIN>'
$t = node "$P/scripts/op-begin.mjs" --op relink; "exit $LASTEXITCODE token=$t"
if ($LASTEXITCODE -eq 0) { node "$P/scripts/init.mjs"; "init exit $LASTEXITCODE" }

$P='<PLUGIN>'; $v=(Get-Location).Path; $tok='11f2032ffad9d878'
$before=@{}; foreach($f in 'index.md','_templates\authored-note.md'){$before[$f]=(Get-FileHash "$v\$f").Hash}
$new=@()
foreach($d in 'raw/clippings','wiki/sources','wiki/entities','wiki/concepts','wiki/syntheses','wiki/authored','moc','log','_templates'){New-Item -ItemType Directory -Force "$v\$d" | Out-Null}
function Put($rel,$src,$content){ $t="$v\$rel"; if(-not(Test-Path $t)){ if($src){Copy-Item $src $t}else{[IO.File]::WriteAllText($t,$content)}; $script:new+=$rel.Replace('\','/') } }
Put 'log.md' $null "# Log`n`nEntries now live one file per operation in the log/ folder. Open **log.base** to browse them.`n"
Put '.gitignore' $null ".wiki-master/`n"
foreach($f in 'vault-schema.md','stale.base','log.base'){Put $f "$P\templates\$f" $null}
foreach($f in Get-ChildItem "$P\templates\_templates" -File){Put "_templates\$($f.Name)" $f.FullName $null}
$new -join "`n"
foreach($k in $before.Keys){"$k unchanged: " + ($before[$k] -eq (Get-FileHash "$v\$k").Hash)}
$env:WIKI_MASTER_VAULT=$v
node "$P/scripts/op-ledger.mjs" add --since $tok @($new | ? {$_ -ne '.gitignore'})
"scaffold done"
